def choose_move(n: int) -> int:
    # Le joueur perd si n est un multiple de 3 (0, 3, 6, 9, etc.)
    # Dans ce cas, on retourne 1 (le choix n'a pas d'importance car on perd)
    # Sinon, on retourne le nombre de jetons à retirer pour laisser un multiple de 3
    if n % 3 == 0:
        return 1
    else:
        return n % 3
```
